  "draw.candidates": ["{n} उम्मीदवार टुकड़े", "{n} అభ్యర్థి స్థలాలు", "{n} candidate parcels"],
  "draw.truth": ["असली सूचना-सूची इन दोनों के बीच कहीं होगी, और वह हमें पता नहीं।", "నిజమైన సమాచార జాబితా ఈ రెండింటి మధ్య ఎక్కడో ఉంటుంది, అది మాకు తెలియదు.", "The real intimation list lies somewhere between these two, and we don't have it."],
  "draw.affected_not_run": ["इस जाँच में यह स्थिति नहीं चलाई जा सकी।", "ఈ పరిశీలనలో ఈ సందర్భం నడపలేదు.", "This scenario could not be run in this inquiry."],
  "draw.affected_too_few": ["आस-पास ऐसे खेत बहुत कम हैं ({n} टुकड़े), इसलिए इनसे ड्रॉ नहीं बन सकता।", "చుట్టుపక్కల అలాంటి పొలాలు చాలా తక్కువ ({n} స్థలాలు), కాబట్టి డ్రా కుదరదు.", "Too few such fields nearby ({n} parcels) to make a draw from them."],
  "draw.field_ref": ["संदर्भ के लिए, आपके खेत का मान:", "సూచన కోసం, మీ పొలం విలువ:", "For reference, your field's value:"],
  "draw.tech_def": ["तकनीकी परिभाषा", "సాంకేతిక నిర్వచనం", "Technical definition"],
  "verify.source": ["ये आँकड़े सीधे सार्वजनिक संग्रह से दोबारा लाए जा रहे हैं, हमारे कैश से नहीं।", "ఈ సమాచారం మా క్యాష్ నుండి కాదు, నేరుగా బహిరంగ ఆర్కైవ్ నుండి మళ్ళీ తెస్తున్నాం.", "This data is being fetched again directly from the public archive, not from our cache."],
  "verify.group_optical": ["प्रकाशीय तस्वीरों से गणना", "ఆప్టికల్ చిత్రాల నుండి లెక్క", "Recomputing from optical images"],
  "verify.group_radar": ["आस-पास का रडार और पानी", "చుట్టుపక్కల రాడార్, నీరు", "Radar and water nearby"],
  "verify.group_history": ["इसी खेत के पिछले साल", "ఇదే పొలం గత సంవత్సరాలు", "This field in past years"],
  "verify.group_village": ["दस खेतों का ड्रॉ", "పది పొలాల డ్రా", "The Ten-Field Draw"],
