  "field.passes_pending": ["सैटेलाइट के गुज़रने की सूची अभी बन रही है।", "ఉపగ్రహ ప్రయాణాల జాబితా ఇంకా తయారవుతోంది.", "The list of satellite passes is still computing."],
  "field.passes_failed": ["सैटेलाइट के गुज़रने की सूची इस बार नहीं बन पाई।", "ఉపగ్రహ ప్రయాణాల జాబితా ఈసారి తయారు కాలేదు.", "The list of satellite passes could not be made this time."],
  "draw.scen_key": ["पट्टी: 90% ड्रॉ का फैलाव। खड़ी रेखा: बीच का औसत। नीला बिंदु: संदर्भ के लिए आपका खेत।", "పట్టీ: 90% డ్రాల వ్యాప్తి. నిలువు గీత: మధ్య సగటు. నీలి చుక్క: సూచన కోసం మీ పొలం.", "Bar: the spread of 90% of draws. Upright line: the middle average. Blue dot: your field, for reference."],
  "verify.title_done": ["दोबारा जाँच का नतीजा", "పునఃతనిఖీ ఫలితం", "The result of the re-check"],
  "verify.title_stored": ["पिछली पूरी जाँच का रिकॉर्ड", "గత పూర్తి తనిఖీ రికార్డు", "The record of the last full check"],
  "verify.lede_stored": ["यह पहले की गई जाँच का रिकॉर्ड है। इस बार कुछ डाउनलोड नहीं हुआ। नीचे के बटन से अभी दोबारा जाँच सकते हैं।", "ఇది ఇంతకు ముందు చేసిన తనిఖీ రికార్డు. ఈసారి ఏమీ డౌన్‌లోడ్ కాలేదు. కింది బటన్‌తో ఇప్పుడే మళ్ళీ తనిఖీ చేయవచ్చు.", "This is the record of a check made earlier. Nothing was downloaded this time. The button below runs it again now."],
  "verify.stored_label": ["पहले की गई जाँच, समय:", "ఇంతకు ముందు చేసిన తనిఖీ, సమయం:", "A stored check, made at:"],
  "verify.stored_body": ["ये संख्याएँ तब सार्वजनिक संग्रह से दोबारा निकाली गई थीं। यह अभी की गणना नहीं है।", "ఈ సంఖ్యలు అప్పుడు బహిరంగ ఆర్కైవ్ నుండి మళ్ళీ లెక్కించారు. ఇది ఇప్పటి లెక్క కాదు.", "These numbers were recomputed from the public archive at that time. This is not a calculation running now."],
  "verify.check_again": ["संग्रह से अभी दोबारा जाँचें", "ఆర్కైవ్ నుండి ఇప్పుడే మళ్ళీ తనిఖీ చేయండి", "Check again from the archive"],
  "verify.check_rest": ["पूरी जाँच फिर चलाएँ", "పూర్తి తనిఖీ మళ్ళీ నడపండి", "Run the full check again"],
