  "ask.citations": ["हवाले", "ఆధారాలు", "Citations"],

  "draw.claim_a": ["बड़े पैमाने की स्थानीय आपदा में धारा 21.5.8 के अनुसार नमूना सर्वे", "విస్తృత స్థానిక విపత్తులో నిబంధన 21.5.8 ప్రకారం నమూనా సర్వే", "In a widespread localized calamity, para 21.5.8 has the sample survey visit"],
  "draw.claim_b": ["बेतरतीब चुने खेतों पर होता है, और उनका औसत सभी सूचनाओं पर लागू होता है। यहाँ उसी तरह के ड्रॉ इस घटना के असली आँकड़ों पर: एक ड्रॉ का औसत कितना हिल सकता है।", "యాదృచ్ఛికంగా ఎంచుకున్న పొలాలలో జరుగుతుంది, వాటి సగటు అన్ని సమాచారాలకు వర్తిస్తుంది. ఇక్కడ అలాంటి డ్రాలు ఈ సంఘటన నిజమైన సమాచారంపై: ఒక డ్రా సగటు ఎంత కదలవచ్చో.", "randomly selected parcels, and their average applies to all intimations. Here are draws of that kind on real data from this event, to show how far one draw's average can move."],
  "draw.your_field": ["आपके खेत का बदलाव", "మీ పొలం మార్పు", "Your field's change"],
  "draw.avg_of_10": ["इस सर्वे के {n} टुकड़ों का औसत", "ఈ సర్వే {n} స్థలాల సగటు", "This survey's average of {n}"],
  "draw.median": ["सभी सर्वे का बीच का औसत", "అన్ని సర్వేల మధ్య సగటు", "Middle average of all surveys"],
  "draw.this_survey": ["यह सर्वे", "ఈ సర్వే", "This survey"],
  "draw.of_surveys": ["कंप्यूटर पर दोहराए {n} सर्वे में से", "కంప్యూటర్‌లో చేసిన {n} సర్వేలలో", "Of {n} surveys simulated on a computer,"],
  "draw.no_fall": ["आपके खेत में इस माप पर गिरावट नहीं दिखी, इसलिए औसत से तुलना का यहाँ कोई अर्थ नहीं बनता। यह भी एक सीधा नतीजा है।", "ఈ కొలతలో మీ పొలంలో తగ్గుదల కనిపించలేదు, కాబట్టి సగటుతో పోలికకు ఇక్కడ అర్థం లేదు. ఇదీ సూటి ఫలితమే.", "Your field shows no fall on this measure, so comparing it with the average means little here. That is a plain result too."],
  "draw.below_half": ["का औसत आपके खेत के बदलाव के आधे से भी कम था।", "సగటు మీ పొలం మార్పులో సగం కన్నా తక్కువ.", "averaged under half of your field's change."],
  "draw.no_half": ["आपके खेत का मान न होने से यह तुलना नहीं बनी।", "మీ పొలం విలువ లేక ఈ పోలిక రాలేదు.", "This comparison needs your field's value, which was not measured."],
  "draw.range_a": ["औसत", "సగటు", "The average moved from"],
  "draw.range_b": ["से", "నుండి", "to"],
  "draw.range_c": ["के बीच घूमता रहा (90% सर्वे)।", "మధ్య కదిలింది (90% సర్వేలు).", "across 90% of surveys."],
  "draw.how_much": ["बेतरतीब चुनाव औसतन निष्पक्ष होता है। यह सिर्फ़ दिखाता है कि इस घटना में एक ड्रॉ का औसत कितना हिल सकता है। यह नहीं कहता कि नियम ग़लत है।", "యాదృచ్ఛిక ఎంపిక సగటున నిష్పక్షపాతం. ఈ సంఘటనలో ఒక డ్రా సగటు ఎంత కదలవచ్చో మాత్రమే ఇది చూపుతుంది. నియమం తప్పని చెప్పదు.", "Random sampling is unbiased on average. This only shows how far one draw's average can move for this event. It does not say the rule is wrong."],
  "draw.hist_aria": ["कंप्यूटर पर दोहराए {n} सर्वे के औसतों का वितरण", "{n} అనుకరణ సర్వేల సగటుల పంపిణీ", "Distribution of averages across {n} simulated surveys"],
  "draw.axis": ["हर खड़ी पट्टी: उतने ड्रॉ जिनका औसत यहाँ गिरा। चिह्न: नक्शे पर दिखे असली ड्रॉ।", "ప్రతి నిలువు పట్టీ: సగటు ఇక్కడ పడిన డ్రాలు. చుక్కలు: మ్యాప్‌లో చూపిన నిజమైన డ్రాలు.", "Each bar counts draws whose average landed there. Dots are the real draws shown on the map."],
  "draw.map_key": ["पीली रेखा: आपका खेत", "పసుపు గీత: మీ పొలం", "Yellow outline: your field"],
  "draw.no_basemap": ["सैटेलाइट नक्शा नहीं चला, इसलिए सिर्फ़ जगहें दिखाई हैं।", "ఉపగ్రహ మ్యాప్ నడవలేదు, స్థలాలు మాత్రమే చూపాం.", "The satellite map did not run, so only the positions are shown."],
