  "verify.working": ["अभिलेखों से आँकड़े दोबारा लाकर {n} संख्याएँ निकाल रहे हैं", "ఆర్కైవ్‌ల నుండి మళ్ళీ తెచ్చి {n} సంఖ్యలు లెక్కిస్తున్నాం", "Fetching the data again from the archives and recomputing {n} numbers"],
  "verify.hash_ok": ["हैश दर्ज रिकॉर्ड से मेल खाता है: खेत की सीमा, तस्वीरों की ID और संख्याएँ मुहर लगने के बाद नहीं बदलीं।", "హాష్ నమోదైన రికార్డుతో సరిపోతుంది: పొలం సరిహద్దు, చిత్రాల ID, సంఖ్యలు ముద్ర తర్వాత మారలేదు.", "The hash matches the stored record: the field boundary, image IDs and numbers have not changed since it was sealed."],
  "verify.scope": ["सैटेलाइट के आँकड़े दोबारा निकाले जाते हैं; नतीजे और मौसम की जाँच केवल छेड़छाड़ के लिए होती है।", "ఉపగ్రహ సంఖ్యలను మళ్ళీ లెక్కిస్తారు; ఫలితం, వాతావరణం మార్చబడలేదని మాత్రమే తనిఖీ చేస్తారు.", "Satellite numbers are recomputed; the verdict and weather are checked for tampering only."],
  "verify.verdict_intact": ["रखा हुआ नतीजा और मौसम मुहर से मेल खाते हैं। ये दोबारा निकाले नहीं गए।", "నిల్వ చేసిన ఫలితం, వాతావరణం ముద్రతో సరిపోతున్నాయి. వీటిని మళ్ళీ లెక్కించలేదు.", "The stored verdict and weather match the seal. They were not recomputed."],
  "verify.verdict_not_sealed": ["यह रिकॉर्ड पुराना है: इसकी मुहर में नतीजा और मौसम शामिल नहीं, इसलिए उनकी जाँच नहीं हो सकती।", "ఇది పాత రికార్డు: దీని ముద్రలో ఫలితం, వాతావరణం లేవు, కాబట్టి వాటిని తనిఖీ చేయలేం.", "This is an older record: its seal does not cover the verdict or weather, so they cannot be checked."],
  "verify.stamp_tampered": ["रिकॉर्ड बदला गया", "రికార్డు మార్చబడింది", "Record altered"],
