  "verify.stamp_partial": ["आंशिक", "పాక్షికం", "Partial"],
  "verify.line_ok": ["सभी {n} संख्याएँ सार्वजनिक आँकड़ों से दोबारा निकलीं और दर्ज संख्याओं से मेल खाती हैं।", "మొత్తం {n} సంఖ్యలు బహిరంగ సమాచారం నుండి మళ్ళీ వచ్చి నమోదైన వాటితో సరిపోయాయి.", "All {n} numbers were recomputed from public data and match the record."],
  "verify.line_bad": ["{n} में से {k} संख्याएँ मेल नहीं खातीं। इस रिकॉर्ड पर भरोसा करने से पहले अंतर देखें।", "{n} లో {k} సంఖ్యలు సరిపోలలేదు. ఈ రికార్డును నమ్మే ముందు తేడా చూడండి.", "{k} of {n} numbers do not match. Examine the differences before relying on this record."],
  "verify.line_partial": ["{n} में से {k} संख्याएँ मेल खाईं। बाकी दोबारा नहीं निकल सकीं।", "{n} లో {k} సంఖ్యలు సరిపోయాయి. మిగిలినవి మళ్ళీ రాలేదు.", "{k} of {n} numbers matched. The rest could not be recomputed."],
  "verify.failed": ["जाँच शुरू नहीं हो पाई। कोई नतीजा नहीं निकाला गया है।", "తనిఖీ మొదలవలేదు. ఫలితం తీయలేదు.", "The check could not start. No result has been drawn."],
  "verify.dropped": ["कनेक्शन टूट गया, इसलिए जाँच अधूरी है। यह असफलता नहीं, बस अधूरा है।", "కనెక్షన్ తెగింది, తనిఖీ అసంపూర్ణం. ఇది వైఫల్యం కాదు, అసంపూర్ణం మాత్రమే.", "The connection dropped, so this check is incomplete. That isn't a failure of the record, only an unfinished check."],
  "verify.again": ["शुरू से दोबारा", "మొదటి నుండి మళ్ళీ", "Start over"],
  "verify.restarted": ["जाँच शुरू से चल रही है।", "తనిఖీ మొదటి నుండి నడుస్తోంది.", "The check is running from the start."],
  "verify.what_used": ["इस्तेमाल हुआ रिकॉर्ड", "ఉపయోగించిన రికార్డు", "The record used"],
  "verify.how_t": ["यह कैसे काम करता है", "ఇది ఎలా పనిచేస్తుంది", "How this works"],
  "verify.how_b": ["हैश खेत की सीमा, सैटेलाइट दृश्यों की ID, बीज, इंजन का संस्करण, संख्याओं, और नतीजे व मौसम के सार (digest) पर बनता है। इनमें से कुछ भी बदले तो हैश बदल जाता है। सैटेलाइट की संख्याएँ दोबारा निकाली जाती हैं। नतीजे और मौसम की केवल छेड़छाड़ के लिए जाँच होती है, वे दोबारा नहीं निकाले जाते। समझाने वाला पाठ और दावे का रास्ता मुहर में नहीं आते। यह दावे का फ़ैसला नहीं है।", "హాష్ పొలం సరిహద్దు, ఉపగ్రహ దృశ్య IDలు, సీడ్, ఇంజిన్ వెర్షన్, సంఖ్యలు, ఫలితం-వాతావరణం సారాంశం (digest) పై ఉంటుంది. ఏది మారినా హాష్ మారుతుంది. ఉపగ్రహ సంఖ్యలను మళ్ళీ లెక్కిస్తారు. ఫలితం, వాతావరణం మార్చబడలేదని మాత్రమే తనిఖీ చేస్తారు, మళ్ళీ లెక్కించరు. వివరణ పాఠం, క్లెయిమ్ దారి ముద్రలో ఉండవు. ఇది క్లెయిమ్ నిర్ణయం కాదు.", "The hash covers the field boundary, satellite scene IDs, seed, engine version, numbers, and a digest of the verdict and weather. Change any of them and the hash changes. The satellite numbers are recomputed. The verdict and weather are only checked for tampering, never recomputed. The explanation text and claim route are not part of the seal. This is not a claim decision."],

  "radar.eyebrow": ["मौसम, पिछले 72 घंटे", "వాతావరణం, గత 72 గంటలు", "Weather, last 72 hours"],
  "radar.title": ["पिछले 72 घंटों में कहाँ भारी बारिश या तूफ़ान का संकेत रहा", "గత 72 గంటల్లో భారీ వర్షం, తుఫాను సంకేతం ఎక్కడ", "Where heavy rain or storm signals appeared in the last 72 hours"],
